contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    bool private callbackEntered;

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        uint contractBefore = address(c).balance;
        uint ownerBefore = c.owner().balance;
        uint thisBefore = address(this).balance;
        callbackEntered = false;

        bool reverted;
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint contractAfter = address(c).balance;
        uint ownerAfter = c.owner().balance;
        uint thisAfter = address(this).balance;

        assert(
            reverted ||
            callbackEntered ||
            (contractAfter == 0 && ownerAfter == ownerBefore + contractBefore + amount && thisAfter == thisBefore)
        );
    }

    receive() external payable {
        callbackEntered = true;
    }
}

