pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {B} from "../src/B.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    B c;
    bool private callbackEntered;

    function setUp() public {
        c = new B();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint contractBefore = address(c).balance;
        uint ownerBefore = c.owner().balance;
        uint thisBefore = address(this).balance;
        callbackEntered = false;
        bool reverted;
        try c.go{value: amount}() { reverted = false; } catch { reverted = true; }
        uint contractAfter = address(c).balance;
        uint ownerAfter = c.owner().balance;
        uint thisAfter = address(this).balance;
        assertTrue(reverted ||
            callbackEntered ||
            (contractAfter == 0 && ownerAfter == ownerBefore + contractBefore + amount && thisAfter == thisBefore));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {
        callbackEntered = true;
    }
}
